def _get_robot_context():
    try:
        from robot.running.context import EXECUTION_CONTEXTS
        return EXECUTION_CONTEXTS.current
    except Exception:
        pass
    return None


def _is_dry_run():
    try:
        current_context = _get_robot_context()
        if current_context.dry_run:
            return True
    except Exception:
        pass
    return False


def _is_robot():
    try:
        current_context = _get_robot_context()
        if current_context is not None:
            return True
    except Exception:
        pass
    return False
